
/* Offline visual prototype. Every record is synthetic. No API, wallet, auth,
   trading, polling, worker or deployment calls are made by this file. */
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = (s='') => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  overview:'<rect x="3" y="3" width="7" height="7" rx="1.3"/><rect x="14" y="3" width="7" height="7" rx="1.3"/><rect x="3" y="14" width="7" height="7" rx="1.3"/><rect x="14" y="14" width="7" height="7" rx="1.3"/>',
  opportunities:'<path d="m3 17 5-5 4 3 8-10"/><path d="M14 5h6v6"/>',
  experiments:'<path d="M9 3h6M10 3v6L4.5 19a1.3 1.3 0 0 0 1.2 2h12.6a1.3 1.3 0 0 0 1.2-2L14 9V3M8 14h8"/>',
  runs:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m10 8 6 4-6 4Z"/>',
  strategies:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',
  system:'<rect x="3" y="4" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 7.5h.01M7 17.5h.01M16 7.5h2M16 17.5h2"/>',
  search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  external:'<path d="M7 17 17 7M7 7h10v10"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.5 7a7.5 7.5 0 0 1 12-2L20 8M4 16l2.5 3a7.5 7.5 0 0 0 12-2"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
  moon:'<path d="M20.8 13.5A9 9 0 0 1 10.5 3.2a9 9 0 1 0 10.3 10.3Z"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',
  more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
  warning:'<path d="m10.3 3.8-8 14A1.5 1.5 0 0 0 3.6 20h16.8a1.5 1.5 0 0 0 1.3-2.2l-8-14a1.6 1.6 0 0 0-2.8 0Z"/><path d="M12 8v5M12 16h.01"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  minus:'<path d="M5 12h14"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  pause:'<path d="M8 5v14M16 5v14"/>',
  play:'<path d="m7 4 14 8-14 8Z"/>',
  stop:'<rect x="5" y="5" width="14" height="14" rx="1"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
  file:'<path d="M14 2H5v20h14V7ZM14 2v6h5M8 12h8M8 16h6"/>',
  code:'<path d="m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18"/>',
  logout:'<path d="M9 4H4v16h5M10 12h12m-4-4 4 4-4 4"/>',
  base:'<circle cx="12" cy="12" r="8"/><path d="M4 12h12"/>',
  solana:'<path d="m5 6 3-2h12l-3 2ZM4 11h13l3 2H7ZM5 18l3-2h12l-3 2Z"/>',
};
function icon(name, cls='icon'){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`;}
function logo(){return '<svg class="brandmark" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="m3 23 7-14h7l-7 14H3Zm12 0 7-14h7l-7 14h-7Z" fill="currentColor"/></svg>';}
function badge(text,tone=''){return `<span class="badge ${tone}">${esc(text)}</span>`;}
function btn(label,action,ico='',cls='',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label?`<span>${label}</span>`:''}</button>`;}
function link(label,page,ico='',cls=''){return `<a class="btn ${cls}" href="#/${page}">${ico?icon(ico):''}<span>${label}</span></a>`;}
function announce(s){$('#announcer').textContent='';setTimeout(()=>$('#announcer').textContent=s,20);}
const NAV=[['overview','Overview'],['opportunities','Opportunities'],['experiments','Experiments'],['runs','Runs'],['strategies','Strategies'],['system','System']];
const FIXTURE_AT='2026-09-19T15:53:23Z';
const freshSessions=()=>[
 {id:'session-paper',name:'Base · Paper',network:'base',mode:'PAPER',state:'STOPPED',health:'UNKNOWN',desired:'1',applied:'1',unresolved:0,heartbeat:null,config:'sha256:paper-fixture-config'},
 {id:'session-base-running',name:'Base · Observe',network:'base',mode:'OBSERVE',state:'RUNNING',health:'HEALTHY',desired:'2',applied:'1',unresolved:0,heartbeat:'2026-09-19T09:00:00Z',config:'sha256:paper-fixture-config'},
 {id:'session-solana-draining',name:'Solana · Paper',network:'solana',mode:'PAPER',state:'DRAINING',health:'DEGRADED',desired:'1',applied:'1',unresolved:2,heartbeat:'2026-09-19T08:55:00Z',config:'sha256:paper-fixture-config'}
];
const records=[{id:'record-1',network:'base',mode:'PAPER',route:'USDC → WETH → USDC',venue:'Uniswap v3 → Uniswap v3',evidence:'REJECTED',reason:'Simulation failed',input:'100000000',output:'100060000',net:null,asset:'fixture:base:usdc',observed:'2026-09-12T12:00:00Z',origin:'SYNTHETIC DATASET'}];
const decisions=[{id:'observation-fixture',state:'CANDIDATE',reason:'Gross quote',gross:'10',origin:'SYNTHETIC DATASET'},{id:'observation-rejected',state:'REJECTED',reason:'Simulation failed',gross:null,origin:'RECORDED LIVE INPUT'}];
// Both entries above are synthetic UI fixtures; the second reproduces a fixture's
// inner origin label, not a claim that this prototype contains real market input.
const costNames=['Network execution','Base L1 data','Relay tip','Funding cost','Account setup','Other transaction costs'];
const state={page:'overview',tab:'',chain:'all',scenario:'snapshot',sessions:freshSessions(),query:'',evidence:'all',dialogTab:'summary',dialogType:'',selected:null,receipts:{},frozen:null,form:{config:'base-paper',reference:'',review:false},costs:costNames.map(()=>({kind:'missing',value:''})),costReview:false,assessment:null,lastPreviewRead:null,recordLayout:'list'};
let focusReturn=null;
let savedTheme='light';try{savedTheme=localStorage.getItem('arb-mobbin-v3-theme')||'light';}catch{}
document.documentElement.dataset.theme=savedTheme==='light'?'light':'dark';
function availableSessions(){return state.scenario==='empty'?[]:state.sessions;}
function visibleSessions(){return availableSessions().filter(s=>state.chain==='all'||s.network===state.chain);}
function matchingRecords(){return (state.scenario==='empty'?[]:records).filter(r=>(state.chain==='all'||r.network===state.chain)&&(state.evidence==='all'||r.evidence===state.evidence)&&(!state.query||`${r.id} ${r.route} ${r.venue} ${r.reason}`.toLowerCase().includes(state.query.toLowerCase())));}
function labelPage(){return NAV.find(x=>x[0]===state.page)?.[1]||(state.page==='real'?'Real trading':'Overview');}
function stateBadge(s){const attn=['DRAINING','FAULTED','RECOVERING'].includes(s);const label=s.charAt(0)+s.slice(1).toLowerCase();return `<span class="state ${attn?'attn':''}">${icon(s==='RUNNING'?'play':s==='STOPPED'?'stop':s==='PAUSED'?'pause':'clock')}${esc(label)}</span>`;}

function chainMark(n){return `<span class="chain-mark">${icon(n)}</span>`;}
function navLink(id,title){return `<a href="#/${id}" class="nav-link ${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span>${id==='runs'?`<span class="nav-count">${availableSessions().length}</span>`:''}</a>`;}
function shell(content){const light=document.documentElement.dataset.theme==='light';return `
<div class="app-frame">
<header class="floating-header">
 <a href="#/overview" class="brand" aria-label="Arbitrage research overview"><span class="brand-tile">${logo()}</span><span>Arbitrage<span class="brand-period">.</span></span></a>
 <nav class="primary-pill" aria-label="Primary navigation">${NAV.map(([id,title])=>`<a href="#/${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav>
 <div class="header-tools">
 ${btn('','search','search','ghost iconbtn','aria-label="Search workspace" title="Search (Cmd or Ctrl K)"')}
 ${btn('','theme',light?'moon':'sun','ghost iconbtn',`aria-label="Switch to ${light?'dark':'light'} theme" title="Switch theme"`)}
 <button class="account-orb" data-action="account" aria-label="Account and preferences">AR</button>
 </div>
</header>
<div class="main-shell"><main id="main" class="workspace">
<div class="workspace-context"><div class="breadcrumbs"><span>Private workspace</span>${icon('chevron')}<strong>${labelPage()}</strong></div><button class="preview-chip" data-action="preview">${icon('code')}<span>Design v3 · Synthetic preview</span></button></div>
${content}
<footer class="footnotes"><div><span class="footer-brand">Arbitrage.</span><p>Research first. Evidence always.</p></div><div><strong>Offline design preview</strong><p>Synthetic snapshot · 19 Sep 2026, 15:53 UTC<br>No accounts, wallets or execution connected.</p></div><div><button class="footer-link" data-action="preview">Explore preview states ${icon('arrow')}</button><p>View filters never change session mode<br>or the explicitly named control scope.</p></div></footer>
</main></div>
<nav class="bottom-nav" aria-label="Mobile navigation">${[['overview','Overview'],['opportunities','Evidence'],['runs','Runs']].map(([id,label])=>`<a href="#/${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('')}<button data-action="mobile-nav" class="${['experiments','strategies','system','real'].includes(state.page)?'active':''}">${icon('more')}<span>More</span></button></nav></div>`;}

function safetyStrip(){return `<div class="notice-strip">${badge('Paper research')}<p>Synthetic data and hypothetical accounting. No automatic paper fills. Closing this page does not stop workers.</p></div>`;}

function pageHead(title,subtitle,action=''){return `<div class="pagehead"><div><h1 tabindex="-1">${title.endsWith('.')?title:title+'.'}</h1><p>${subtitle}</p></div><div class="head-actions"><div class="grow-mobile"><label class="sr-only" for="chain-filter">View chain, view filter only</label><select id="chain-filter" aria-describedby="scope-note"><option value="all" ${state.chain==='all'?'selected':''}>All chains</option><option value="base" ${state.chain==='base'?'selected':''}>Base</option><option value="solana" ${state.chain==='solana'?'selected':''}>Solana</option></select></div>${action||btn('Re-read fixture','refresh','refresh')}<span class="sr-only" id="scope-note">View filter only. Stop controls retain their explicitly named session scope.</span></div></div>`;}

function fixtureNotice(){if(state.scenario==='stale')return `<div class="inline-message">${badge('Stale / last known','warn')}<p><strong>Last known snapshot retained.</strong> The preview is showing a stale-data state. A received API response does not establish feed freshness or worker health. Observed states are not changed by a pending request.</p></div>`;if(state.scenario==='error')return `<div class="inline-message danger" role="alert"><p><strong>Connection degraded — last known snapshot retained.</strong> This is a simulated error. In production, no synthetic records may be substituted.</p>${btn('Restore fixture view','restore','refresh','small space')}</div>`;if(state.lastPreviewRead)return `<p class="subtle" style="margin:-10px 0 17px" role="status">Fixture view re-read locally. Source timestamps and captured prices are unchanged.</p>`;return '';}
function loadingView(){return `<div class="empty" role="status"><div class="empty-icon">${icon('clock')}</div><h2>Loading service records</h2><p>Previewing the loading state. In production, wait for sessions, capabilities and opportunity responses. Do not display fallback market data.</p>${btn('Restore fixture view','restore','refresh')}</div>`;}
function emptyView(title,text){return `<div class="empty"><div class="empty-icon">${icon('file')}</div><h2>${title}</h2><p>${text}</p>${btn('Reset view filters','reset-filter','refresh')}</div>`;}
function stat(label,value,meta,index,word=false){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value ${word?'word':''}">${value}${word?'':`<span class="stat-unit">${index===3?'record':'sessions'}</span>`}</div><div class="stat-meta">${meta}</div></div>`;}

function sessionRows(){return visibleSessions().map(s=>`<div class="session-row"><div class="flex">${chainMark(s.network)}<div class="grow"><div class="session-name">${esc(s.name)}</div><div class="session-note">${s.desired!==s.applied?'Revision gap':s.unresolved?`${s.unresolved} unresolved attempts`:s.state==='RECOVERING'?'Readiness not confirmed':'Immutable configuration'}</div></div></div><div>${stateBadge(s.state)}${state.receipts[s.id]?`<div class="session-note">${esc(state.receipts[s.id].action)} · ${state.receipts[s.id].status}</div>`:''}</div><div class="session-meta"><strong>${esc(s.mode==='OBSERVE'?'Observe':'Paper')}</strong>Session mode</div>${btn('','session','external','ghost iconbtn',`data-id="${s.id}" aria-label="Inspect ${esc(s.name)} session"`)}</div>`).join('');}

function readiness(){return `<section class="panel readiness-panel"><div class="panel-head"><div><p class="section-eyebrow">Record-1 · Synthetic evidence</p><h2>What the evidence supports.</h2></div><span class="section-icon">${icon('shield')}</span></div><div class="gate-list">
${[['check','Capture','Record and provenance retained','Retained','done'],['close','Simulation','This route did not pass','Failed','blocked'],['minus','Explicit costs','Missing costs are not zero','Incomplete',''],['lock','Execution eligibility','No executable result established','Unknown','']].map(([i,t,d,b,c])=>`<div class="gate"><span class="gate-symbol ${c}">${icon(i)}</span><div class="grow"><h3>${t}</h3><p>${d}</p></div><span class="gate-label">${b}</span></div>`).join('')}
</div><div class="gate-end">${icon('info')}<span>A gross quote is not a realized result.</span></div></section>`;}

function overview(){const ss=visibleSessions();const rr=matchingRecords();const att=ss.filter(s=>s.unresolved>0||s.desired!==s.applied).length;const draining=ss.filter(s=>s.unresolved>0);return safetyStrip()+pageHead('Research, at a glance.','Sessions, captured evidence, and the checks that still need attention.',link('New experiment','experiments','plus','primary'))+fixtureNotice()+(state.scenario==='loading'?loadingView():`
<div class="stats">${stat('Research sessions',String(ss.length).padStart(2,'0'),'Loaded snapshot · current chain view',1)}${stat('Need attention',String(att).padStart(2,'0'),'Unresolved attempts or revision gaps',2)}${stat('Captured evidence',String(rr.length).padStart(2,'0'),'Loaded page · not your full history',3)}${stat('Net after costs',rr.length?'Unknown':'No record',rr.length?'Costs incomplete · never treated as zero':'No evidence in this view',4,true)}</div>
${ss.length?`<div class="overview-grid"><section class="panel sessions-panel"><div class="panel-head"><div><p class="section-eyebrow">Your workspace</p><h2>Research sessions.</h2></div><a class="btn small soft-link" href="#/runs">View all ${icon('arrow')}</a></div>
${draining.length?`<div class="attention">${icon('warning')}<p><strong>${esc(draining[0].name)} needs review.</strong><br>${draining[0].unresolved} previously emitted attempts remain unresolved.</p><button class="review-arrow" data-action="session" data-id="${esc(draining[0].id)}" aria-label="Review unresolved attempts">${icon('arrow')}</button></div>`:''}
${sessionRows()}<div class="panel-foot">${icon('info')}<span>A requested action is not an applied worker state.</span></div></section>${rr.length?readiness():`<section class="panel pad"><h2>Evidence readiness.</h2><p class="subtle space">No captured record in this chain view. No readiness conclusion is available.</p></section>`}</div>`:emptyView('No sessions in this view','Create a session from an operator-validated configuration in Experiments. The chain filter changes only this view.')}
<section class="panel latest-panel"><div class="panel-head"><div><p class="section-eyebrow">From the loaded snapshot</p><h2>Latest captured evidence.</h2></div><a class="btn small soft-link" href="#/opportunities">Explore evidence ${icon('arrow')}</a></div>${recordTable()}<div class="panel-foot">${icon('file')}<span>${rr.length} ${rr.length===1?'record':'records'} on the loaded page. Exact start-asset minor units; decimal scale not supplied. Synthetic data only.</span></div></section>`);}

function evidenceViewControl(){return `<div class="view-switch" role="group" aria-label="Captured evidence layout">${[['list','List','more'],['cards','Cards','overview']].map(([id,label,i])=>`<button data-action="evidence-layout" data-layout="${id}" aria-pressed="${state.recordLayout===id}" class="${state.recordLayout===id?'active':''}">${icon(i)}<span>${label}</span></button>`).join('')}</div>`;}
function evidenceCards(rr){return `<div class="evidence-gallery">${rr.map(r=>`<article class="evidence-tile"><div class="evidence-tile-top"><span class="token-stack"><span class="token-tile">$</span><span class="token-tile eth">Ξ</span></span><span class="pill-meta">Base · Paper</span></div><div class="evidence-tile-body"><p class="section-eyebrow">${esc(r.id)} · Synthetic dataset</p><h3>${esc(r.route)}</h3><p class="subtle">${esc(r.venue)}</p><div class="tile-verdict">${icon('close')}<span><strong>Rejected</strong> · Simulation failed</span></div><dl class="tile-values"><div><dt>Input · minor units</dt><dd class="mono">${esc(r.input)}</dd></div><div><dt>Net after costs</dt><dd>Unknown</dd><small>Costs incomplete</small></div></dl></div><footer><span>12 Sep 2026 · 12:00 UTC</span>${btn('Inspect evidence','record','arrow','primary',`data-id="${esc(r.id)}"`)}</footer></article>`).join('')}</div>`;}
function recordTable(){const rr=matchingRecords();if(rr.length&&state.page==='opportunities'&&state.recordLayout==='cards')return evidenceCards(rr);if(!rr.length)return `<div style="padding:20px">${emptyView('No captured records in this view','No matching record was found. Missing evidence is not a zero trading result.')}</div>`;return `<div class="desktop-records table-wrap"><table><caption class="sr-only">Captured market records. All prototype data is synthetic. Amounts are exact start-asset minor units.</caption><thead><tr><th>Route / chain</th><th>Evidence</th><th class="align-right">Input · minor units</th><th>Net · minor units</th><th></th></tr></thead><tbody>${rr.map(r=>`<tr><td><div class="route-flow">USDC ${icon('arrow')} WETH ${icon('arrow')} USDC</div><p class="subtle">Uniswap v3 · Base · ${r.id}</p></td><td>${badge('Rejected','warn')}<div class="subtle">Simulation failed</div></td><td class="align-right mono">${r.input}</td><td><strong>Unknown</strong><p class="subtle">Costs incomplete</p></td><td>${btn('Inspect','record','external','small',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-records">${rr.map(r=>`<article class="record-card"><div class="flex spread"><div class="route-flow">USDC ${icon('arrow')} WETH ${icon('arrow')} USDC</div></div><p class="subtle" style="margin-top:6px">Uniswap v3 · Base · record-1</p><div style="margin-top:13px">${badge('Rejected · simulation failed','warn')}</div><dl class="summary-list"><div><dt>Input · minor units</dt><dd class="mono">${r.input}</dd></div><div><dt>Net · minor units</dt><dd>Unknown — costs incomplete</dd></div><div><dt>Observed</dt><dd>12 Sep 2026, 12:00 UTC</dd></div></dl>${btn('Inspect evidence','record','arrow','',`data-id="${r.id}"`)}</article>`).join('')}</div>`;}
function tabs(items,active){return `<div class="tabs" role="tablist" aria-label="${labelPage()} workspaces">${items.map(([id,label,count])=>`<button class="tab ${active===id?'active':''}" id="tab-${id}" role="tab" aria-selected="${active===id}" aria-controls="tab-content" tabindex="${active===id?'0':'-1'}" data-action="tab" data-tab="${id}">${label}${count!==undefined?`<span class="tab-count">${count}</span>`:''}</button>`).join('')}</div>`;}
function opportunityPage(){const tab=['captured','decisions','costs','exports'].includes(state.tab)?state.tab:'captured';let content='';if(tab==='captured')content=`<div class="toolbar"><div class="search">${icon('search')}<label class="sr-only" for="record-search">Search captured records</label><input id="record-search" placeholder="Search route, record or reason…" value="${esc(state.query)}"></div><label class="sr-only" for="evidence-filter">Evidence state</label><select id="evidence-filter"><option value="all">All evidence</option><option value="REJECTED" ${state.evidence==='REJECTED'?'selected':''}>Rejected</option><option value="CANDIDATE" ${state.evidence==='CANDIDATE'?'selected':''}>Candidate</option></select>${evidenceViewControl()}</div><section class="panel evidence-panel"><div id="records-area">${recordTable()}</div><div class="panel-foot">The API process does not collect market data. Workers may independently persist captured evidence; returned records and provider status must be assessed separately.</div>${pagination('1 record · loaded page')}</section>`;
if(tab==='decisions')content=decisionView();if(tab==='costs')content=costView();if(tab==='exports')content=exportView();return safetyStrip()+pageHead('Opportunities','Inspect evidence. Separate quotes, decisions, and hypothetical assumptions.')+fixtureNotice()+tabs([['captured','Captured records',matchingRecords().length],['decisions','Decision evidence'],['costs','Cost research'],['exports','Exports & audit']],tab)+`<section id="tab-content" role="tabpanel" aria-labelledby="tab-${tab}">${state.scenario==='loading'?loadingView():content}</section>`;}
function pagination(label){return `<div class="pagination"><span>${label} · not a full-history total</span><div class="flex">${btn('Previous','noop','','small','disabled aria-label="No previous fixture page"')}${btn('Next','noop','','small','disabled aria-label="No next fixture page"')}</div></div>`;}
function decisionView(){return `<div class="toolbar"><div><p class="subtle">Decision session</p><div class="flex" style="margin-top:5px"><strong style="font-size:13px">session-paper</strong>${badge('Base · Paper')}</div></div>${badge('Persisted evidence')}</div><div class="mini-stats">${[['Stored observations','3'],['Quoted candidates','1'],['Rejected / unavailable','1 / 1']].map(([t,v])=>`<div class="mini-stat"><span class="subtle">${t}</span><strong>${v}</strong></div>`).join('')}</div><p class="subtle" style="margin-bottom:16px">Fixture-session aggregate: three observations. The loaded detail page below contains two entries. A unique quote group is not a profitable trade.</p><section class="panel"><div class="panel-head"><div><h2>Raw decision observations</h2><p>2 entries on this loaded page · original observations stay immutable</p></div></div><div class="table-wrap"><table><caption class="sr-only">Two synthetic decision observations. Inner origin labels reproduce test fixture labels.</caption><thead><tr><th>Observation / origin label</th><th>Result / reason</th><th class="align-right">Gross delta · minor units</th><th>Evidence</th></tr></thead><tbody>${decisions.map(d=>`<tr><td><strong class="mono">${d.id}</strong><div class="subtle">Base · session-paper</div><div style="margin-top:8px">${badge(d.origin)}</div><p class="subtle">Synthetic UI fixture, including origin label</p></td><td>${badge(d.state,d.state==='REJECTED'?'warn':'')}<div class="subtle">${d.reason}</div></td><td class="align-right mono">${d.gross===null?'Unknown':'+'+d.gross}</td><td>${btn('Inspect','decision','external','small',`data-id="${d.id}"`)}</td></tr>`).join('')}</tbody></table></div>${pagination('2 entries')}</section><div class="inline-message neutral space"><p>External costs and full transaction simulation remain outside this gross quote. Quotes alone do not establish arbitrage profit. Source continuity, freshness, simulation and cost completeness are separate checks.</p></div>`;}
function exactCost(){if(state.costs.some(c=>c.kind==='missing'||(c.kind==='known'&&!/^\d+$/.test(c.value))))return null;return (10n-state.costs.reduce((sum,c)=>sum+(c.kind==='zero'?0n:BigInt(c.value)),0n)).toString();}
function costView(){const net=exactCost();return `<div class="form-layout"><div><section class="panel"><div class="panel-head"><div><h2>Hypothetical cost research</h2><p>Retained candidate · observation-fixture</p></div>${badge('Manual assumptions','warn')}</div><div class="cost-header">All inputs below are manually valued <strong>start-asset minor units</strong> in this design fixture. An empty amount is unknown, not zero.</div>${costNames.map((name,i)=>`<div class="cost-row"><label for="cost-kind-${i}">${name}<small>${i===0?'Priority fee belongs in execution; do not subtract it twice.':'Explicit scenario assumption · not an observed cost'}</small></label><select id="cost-kind-${i}" data-cost-kind="${i}" aria-label="${name} treatment"><option value="missing" ${state.costs[i].kind==='missing'?'selected':''}>Missing · unknown</option><option value="zero" ${state.costs[i].kind==='zero'?'selected':''}>Explicit zero</option><option value="known" ${state.costs[i].kind==='known'?'selected':''}>Known manual amount</option></select><input id="cost-value-${i}" data-cost-value="${i}" inputmode="numeric" pattern="[0-9]+" value="${esc(state.costs[i].value)}" placeholder="Minor units" aria-label="${name} in start-asset minor units" ${state.costs[i].kind!=='known'?'disabled':''}></div>`).join('')}<div class="panel-foot">Native-asset costs require a separate, explicit conversion ratio and valuation time in production. This prototype demonstrates the presentation, not that valuation pipeline.</div></section><div class="inline-message neutral space"><p>Pool fees already included in a quote must not be deducted again. Saving a scenario creates no paper bookings and changes no quote.</p></div></div><aside class="panel pad review-card"><p class="eyebrow">Scenario preview</p><h2 class="space">Net after entered costs</h2><div class="cost-result" id="cost-result">${net===null?'Unknown':(BigInt(net)>0?'+':'')+net}</div><p class="subtle">Start-asset minor units · hypothetical</p><dl class="summary-list space"><div><dt>Retained gross delta</dt><dd class="mono">+10</dd></div><div><dt>Cost completeness</dt><dd id="cost-completeness">${net===null?'Incomplete':'All six entered'}</dd></div><div><dt>Funding / overhead</dt><dd>Scenario inputs only</dd></div><div><dt>Execution eligibility</dt><dd>Not established</dd></div></dl><label class="check-label space"><input id="cost-review" type="checkbox" ${state.costReview?'checked':''}><span>I reviewed the exact units, conversion assumptions and hypothetical inputs.</span></label>${btn('Save local scenario','save-cost','file','primary',`${net===null||!state.costReview?'disabled':''} id="save-cost"`)}<p class="form-help space">Stored in this page’s memory only. No server assessment or real outcome is created.</p>${state.assessment?`<p class="form-notice" role="status">Local scenario retained. Net: ${esc(state.assessment.net)} minor units. The original observation is unchanged.</p>`:''}</aside></div>`;}
function exportView(){return `<div class="form-layout"><section class="panel"><div class="panel-head"><div><h2>Freeze a session snapshot</h2><p>Selected scope: session-paper · Base · PAPER</p></div>${badge(state.frozen?'Frozen export':'Snapshot export')}</div><div class="freeze-box"><p style="font-size:12px">Keep an immutable copy of the preview’s sample evidence and assumptions. This is a <strong>synthetic design export</strong>, not a complete database session export.</p><dl class="summary-list"><div><dt>Captured records</dt><dd>1 fixture</dd></div><div><dt>Decision observations</dt><dd>2 fixture entries</dd></div><div><dt>Cost assessments</dt><dd>${state.assessment?'1 local scenario':'0 saved scenarios'}</dd></div><div><dt>Source snapshot time</dt><dd class="mono">${FIXTURE_AT}</dd></div><div><dt>Freeze state</dt><dd>${state.frozen?'Frozen in this page’s memory':'Not prepared'}</dd></div></dl><div class="flex wrap space">${btn(state.frozen?'Prepare a new snapshot':'Prepare frozen snapshot','freeze','file',state.frozen?'':'primary')}${btn('Download JSON','export-json','download','',state.frozen?'':'disabled')}${btn('Download CSV','export-csv','download','',state.frozen?'':'disabled')}</div><p class="form-help space">Downloading does not refresh the frozen object. CSV contains the captured record only; JSON also includes the decision fixtures and any saved scenario.</p></div></section><section class="panel pad"><div class="flex spread"><h2>Capture audit</h2>${icon('shield')}</div><dl class="summary-list space"><div><dt>Capture catalog</dt><dd>Sample reference only</dd></div><div><dt>Raw artifact bytes</dt><dd>Not included</dd></div><div><dt>Integrity verification</dt><dd>Not performed</dd></div><div><dt>Collection coverage</dt><dd>Unknown</dd></div></dl><div class="inline-message neutral space" style="margin-bottom:0"><p>An export is not proof of uninterrupted activity, executable opportunities, or realized profit.</p></div></section></div>`;}
function experimentPage(){const chosen=configFor(state.form.config);return safetyStrip()+pageHead('Experiments','Create a research session from a validated, immutable configuration.')+fixtureNotice()+`<div class="form-layout"><form class="panel" id="experiment-form"><section class="form-section"><div class="step-heading"><span class="step-number">01</span><h2>Select a configuration</h2></div><div class="field"><label for="experiment-config">Validated configuration</label><select id="experiment-config"><option value="base-paper" ${state.form.config==='base-paper'?'selected':''}>Base · PAPER · paper-fixture-config</option><option value="base-observe" ${state.form.config==='base-observe'?'selected':''}>Base · OBSERVE · observe-fixture-config</option><option value="solana-paper" ${state.form.config==='solana-paper'?'selected':''}>Solana · PAPER · solana-fixture-config</option></select><p class="form-help">Fixture catalog. Production must use the operator-validated configuration registry, not editable modes or token names.</p></div></section><section class="form-section"><div class="step-heading"><span class="step-number">02</span><h2>Define the session</h2></div><div class="field"><label for="experiment-network">Session network</label><input id="experiment-network" value="${chosen.network==='base'?'Base':'Solana'}" readonly><p class="form-help">Bound to the selected configuration. The view filter does not change this network.</p></div><div class="field"><label for="experiment-reference">Experiment reference</label><input id="experiment-reference" placeholder="e.g. base-fee-sensitivity-01" maxlength="100" value="${esc(state.form.reference)}" autocomplete="off"><p class="form-help">A human-readable reference, separate from the immutable session ID.</p></div></section><section class="form-section"><div class="step-heading"><span class="step-number">03</span><h2>Review before creating</h2></div><div class="inline-message neutral" style="margin-bottom:8px"><p>Virtual principal, native fee reserves, token eligibility and delay scenarios come from the validated configuration. This API does not expose their detailed values yet; review the source configuration before confirming.</p></div><label class="check-label"><input id="experiment-review" type="checkbox" ${state.form.review?'checked':''}><span>I reviewed the source configuration, including virtual principal and separate native fee reserves.</span></label></section></form><aside class="panel pad review-card"><div class="flex spread"><h2>Immutable settings</h2>${icon('lock')}</div><dl class="summary-list space"><div><dt>Mode</dt><dd>${badge(chosen.mode)}</dd></div><div><dt>Network</dt><dd>${chosen.network==='base'?'Base':'Solana'}</dd></div><div><dt>Configuration</dt><dd class="mono">${chosen.config}</dd></div><div><dt>Strategy</dt><dd>usdc-cycle</dd></div><div><dt>After creation</dt><dd>Recovery / readiness check</dd></div></dl><div class="inline-message neutral space"><p><strong>Creating a session does not start a worker.</strong> Recovery must finish before a stopped session can start.</p></div>${btn('Create preview session','create-session','plus','primary',`${!state.form.review||!state.form.reference.trim()?'disabled':''} id="create-session"`)}<p class="form-help space">Local prototype only. LIVE is unavailable. No production configuration, session or command is created.</p></aside></div>`;}
function configFor(id){return id==='base-observe'?{network:'base',mode:'OBSERVE',config:'sha256:observe-fixture-config'}:id==='solana-paper'?{network:'solana',mode:'PAPER',config:'sha256:solana-fixture-config'}:{network:'base',mode:'PAPER',config:'sha256:paper-fixture-config'};}
function runsPage(){const tab=['sessions','ledger','journal','reservations'].includes(state.tab)?state.tab:'sessions';let c='';if(tab==='sessions')c=`<div class="toolbar"><p class="subtle">${visibleSessions().length} sessions in view · ${availableSessions().length} loaded across all chains</p>${btn(`Stop ${stoppable().length} loaded sessions`,'stop-all','stop','danger',stoppable().length?'':'disabled')}</div>${visibleSessions().length?`<section class="panel"><div class="panel-head"><div><h2>Research sessions</h2><p>Open a session to inspect state, receipts and available commands.</p></div>${badge('Immutable')}</div>${sessionRows()}<div class="panel-foot">Bulk control always names its loaded-session scope, independent of the chain filter. Separately launched capture processes have their own lifecycle.</div></section>`:emptyView('No sessions in this view','The current view has no matching sessions. Configuration and existing commands are not changed.')}<div class="inline-message neutral space"><p>Desired and applied revision differences do not, by themselves, establish a pending worker acknowledgement. Only explicit command receipts establish the command’s status.</p></div>`;
if(tab==='ledger')c=ledgerView();if(tab==='journal')c=journalView();if(tab==='reservations')c=reservationView();return safetyStrip()+pageHead('Runs','Manage session lifecycles. Keep hypothetical accounting separate.')+fixtureNotice()+tabs([['sessions','Research sessions',availableSessions().length],['ledger','Paper ledger'],['journal','Journal'],['reservations','Reservations']],tab)+`<section id="tab-content" role="tabpanel" aria-labelledby="tab-${tab}">${state.scenario==='loading'?loadingView():c}</section>`;}
function ledgerView(){return `<div class="toolbar"><div><p class="subtle">Paper session / run</p><strong style="font-size:13px">session-paper / run-original</strong></div>${badge('Hypothetical')}</div><div class="inline-message neutral"><p>Balances are inventory, not returns. Automatic fills and settlement are not enabled. These exact minor-unit values are synthetic layout fixtures, not a measured portfolio.</p></div><section class="panel"><div class="panel-head"><div><h2>Hypothetical balances</h2><p>Native fee asset · separate from principal inventory</p></div>${btn('Export sample','export-ledger','download','small')}</div><div class="balance-grid">${[['Free','80'],['Reserved','20'],['Total','100']].map(([t,n])=>`<div class="balance"><span class="subtle">${t}</span><strong>${n}</strong><span class="subtle">Native fee asset · minor units</span></div>`).join('')}</div><div class="panel-foot">Principal inventory, fee inventory and valuation must never be summed without an explicit, supported conversion.</div></section><section class="panel pad space"><h2>Initialize a hypothetical run</h2><p class="subtle space">A new ledger uses the session’s frozen configuration. Existing runs and initial balances remain unchanged.</p><p class="subtle space">Run creation is intentionally not wired in this visual prototype. Its production form must retain validated token identity, exact initial principal, a separate native fee reserve, and the source-configuration acknowledgement.</p>${btn('Review required fields','run-fields','file','space')}</section>`;}
function journalView(){return `<div class="toolbar"><div><p class="subtle">Selected paper run</p><strong style="font-size:13px">run-original · sample journal</strong></div>${badge('Hypothetical')}</div><section class="panel"><div class="panel-head"><div><h2>Paper journal</h2><p>Stored commands and double-entry postings in original asset units.</p></div></div><div class="timeline"><div class="timeline-event"><span class="eyebrow">12 Sep 2026 · 12:00 UTC</span><h3 style="margin-top:8px">Initialize sample fee inventory</h3><p>Debit available inventory: 100 minor units.<br>Credit initial capital: 100 minor units.</p><div class="raw-block">Asset: fixture:base:native-fee-asset\nCommand: sample-initialize\nSource: synthetic interface fixture</div></div><div class="timeline-event"><span class="eyebrow">Captured evidence</span><h3 style="margin-top:8px">No automatic paper fill posted</h3><p>A retained gross quote or saved cost assumption does not create a journal entry.</p></div></div><div class="panel-foot">The sample timeline illustrates layout only. Production entries must come from the journal endpoint, not reconstructed from UI totals.</div></section>`;}
function reservationView(){return `<div class="toolbar"><div><p class="subtle">Selected paper run</p><strong style="font-size:13px">run-original</strong></div>${badge('Recorded attempts')}</div><section class="panel"><div class="panel-head"><div><h2>Reservation history</h2><p>Original requests and reconciliation state — not current free inventory.</p></div></div><div class="table-wrap"><table><caption class="sr-only">One synthetic reservation request. Amounts refer to different assets.</caption><thead><tr><th>Attempt</th><th class="align-right">Principal requested</th><th class="align-right">Native fee budget</th><th>State</th></tr></thead><tbody><tr><td class="mono">attempt-fixture</td><td class="align-right mono">9</td><td class="align-right mono">20</td><td>${badge('Unknown','warn')}</td></tr></tbody></table></div><div class="panel-foot">The values use their respective original asset minor units. Request history does not prove that inventory is still reserved.</div></section>`;}
function strategiesPage(){return safetyStrip()+pageHead('Strategies','A read-only registry of immutable, validated configurations.')+fixtureNotice()+`<section class="panel"><div class="panel-head"><div><h2>Configuration register</h2><p>Synthetic catalog · no strength scores or profitability ranking</p></div>${badge('Immutable')}</div><div class="table-wrap"><table><caption class="sr-only">Synthetic strategy configurations. Selecting one does not enable execution.</caption><thead><tr><th>Configuration</th><th>Network</th><th>Mode</th><th>Strategy</th><th></th></tr></thead><tbody>${[['base-paper','Base paper research'],['base-observe','Base observation'],['solana-paper','Solana paper research']].map(([id,title])=>{let c=configFor(id);return `<tr><td><strong>${title}</strong><p class="subtle mono break">${c.config}</p></td><td>${c.network==='base'?'Base':'Solana'}</td><td>${badge(c.mode)}</td><td>usdc-cycle</td><td>${btn('Inspect','config','external','small',`data-id="${id}"`)}</td></tr>`;}).join('')}</tbody></table></div><div class="panel-foot">Pools, amounts and scenario changes require a separately validated configuration revision. Existing session modes and digests cannot be edited.</div></section>`;}
function systemPage(){const tab=['health','collection','capabilities'].includes(state.tab)?state.tab:'health';let c=tab==='health'?`<div class="system-grid">${[['system','API connection','Not connected','This offline design preview sends no API requests.'],['runs','Worker state','Fixture states','RUNNING in a fixture does not prove a real worker is active.'],['clock','Market data','No live feed','Captured timestamps and original evidence stay visible.']].map(([i,t,v,p])=>`<section class="panel system-card">${icon(i)}<h3>${t}</h3><div class="system-value">${v}</div><p>${p}</p></section>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Adapter support</h2><p>Catalog participation is not runtime qualification.</p></div></div><div class="table-wrap"><table><caption class="sr-only">Adapter support display contract; no live checks are performed in the prototype.</caption><thead><tr><th>Adapter</th><th>Role</th><th>Runtime qualification</th><th>Evidence</th></tr></thead><tbody><tr><td><div class="flex">${chainMark('base')}Base / EVM</div></td><td>Research collection</td><td>Not checked</td><td>Offline fixture</td></tr><tr><td><div class="flex">${chainMark('solana')}Solana</div></td><td>Research collection</td><td>Not checked</td><td>Offline fixture</td></tr></tbody></table></div></section>`:tab==='collection'?`<section class="panel pad"><h2>Collection health</h2><p class="subtle space">Select a collection session in production to inspect its source continuity, stored checkpoints, provider errors and capture history.</p><dl class="summary-list space"><div><dt>Continuous collection</dt><dd>Not established by this preview</dd></div><div><dt>Checkpoint progress</dt><dd>Not available</dd></div><div><dt>Captured evidence</dt><dd>1 synthetic market record</dd></div><div><dt>Artifact bytes</dt><dd>Not included</dd></div><div><dt>API connection ≠ feed health</dt><dd>Separate evidence required</dd></div></dl></section>`:`<section class="panel"><div class="panel-head"><div><h2>Capabilities</h2><p>Production sections are gated by /v1/capabilities, not UI assumptions.</p></div></div><div class="table-wrap"><table><caption class="sr-only">Required capability gates for the production redesign.</caption><thead><tr><th>Capability</th><th>Workspace</th><th>Preview</th></tr></thead><tbody>${[['decision_history','Decision evidence'],['paper_ledger','Paper ledger / journal'],['paper_run_creation','New hypothetical run'],['collection_telemetry','Collection health'],['session_export','Frozen session export'],['cost_assessments','Cost research'],['adapter_support','Adapter catalog']].map(([k,v])=>`<tr><td class="mono">${k}</td><td>${v}</td><td>Layout only</td></tr>`).join('')}</tbody></table></div><div class="panel-foot">Absent, disabled, unavailable and stale are distinct states. A navigation item does not grant a backend capability.</div></section>`;return safetyStrip()+pageHead('System','Inspect API connectivity, worker state, and source health separately.')+fixtureNotice()+tabs([['health','Health & adapters'],['collection','Collection'],['capabilities','Capabilities']],tab)+`<section id="tab-content" role="tabpanel" aria-labelledby="tab-${tab}">${c}</section>`;}
function realPage(){return pageHead('Real trading','A separate workspace. Existing session modes never change.')+`<section class="panel locked-panel"><div class="locked-icon">${icon('lock')}</div>${badge('Not available')}<h2>Real trading is not available</h2><p>Live execution has not been enabled. No real orders can be sent from this workspace.</p><p>This release has no wallet connection, signing or live order submission. Switching workspaces never changes the mode of an existing session.</p>${btn('Start real trading','noop','lock','','disabled')}<br>${link('Return to paper workspace','overview','arrow','ghost')}</section>`;}
function signinPage(){return `<div class="sign-shell"><header class="sign-header"><a href="#/overview" class="brand">${logo()}Arbitrage</a>${btn('Theme','theme','sun','ghost')}</header><main class="sign-main" id="main"><section class="sign-context"><p class="eyebrow">Arbitrage / research workspace</p><h2>Research first.<br>Evidence always.</h2><p>A private workspace for immutable sessions, captured observations, and explainable decisions.</p><div class="gate-list">${[['file','Capture','Keep the original observation.'],['shield','Inspect','Separate facts from assumptions.'],['lock','Preserve','Make each decision reproducible.']].map(([i,t,p])=>`<div class="gate"><span class="gate-symbol">${icon(i)}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></section><section class="signin-card">${badge('Design preview')}<h1 tabindex="-1">Welcome back.</h1><p>Use your email address and password to access Paper trading and Real trading.</p><div class="field"><label for="signin-email">Email address</label><input id="signin-email" type="email" placeholder="you@your-workspace.com" disabled></div><div class="field"><label for="signin-password">Password</label><input id="signin-password" type="password" placeholder="Your password" disabled></div>${link('Open workspace preview','overview','arrow','primary')}<button class="text-link" data-action="signin-help" aria-expanded="false" aria-controls="signin-help">First time here or forgot your password?</button><div id="signin-help" class="inline-message neutral" hidden><p>Use the private account setup or recovery link supplied by the workspace owner. There is no public registration. Recovery links expire after 30 minutes and work once; no reset email has been sent.</p></div><div class="signin-foot">This prototype does not collect or submit credentials. The production sign-in uses the existing account API. No wallet or exchange credentials are requested here.</div></section></main><footer class="sign-footer">Design v3 · Synthetic interface preview · No account or trading connection</footer></div>`;}
function render(focus=false){const views={overview,opportunities:opportunityPage,experiments:experimentPage,runs:runsPage,strategies:strategiesPage,system:systemPage,real:realPage};$('#app').innerHTML=state.page==='signin'?signinPage():shell((views[state.page]||overview)());document.title=`${state.page==='signin'?'Sign in':labelPage()} · Arbitrage Research · Mobbin v3 preview`;if(focus){$('h1')?.focus({preventScroll:true});window.scrollTo(0,0);}}
function route(){const value=location.hash.replace(/^#\/?/,'')||'overview';const [page,q='']=value.split('?');const next=new URLSearchParams(q);state.page=[...NAV.map(x=>x[0]),'signin','real'].includes(page)?page:'overview';state.tab=next.get('tab')||'';if($('#dialog').open)$('#dialog').close();render(true);}
function navigate(page,tab=''){location.hash=`/${page}${tab?'?tab='+tab:''}`;}
function openDialog(title,body,{eyebrow='Synthetic design fixture',drawer=false,footer=''}={}){const d=$('#dialog');if(!d.open)focusReturn=document.activeElement;d.className=drawer?'drawer':'';d.innerHTML=`<div class="dialog-inner"><header class="dialog-head"><div><p class="eyebrow">${eyebrow}</p><h2 id="dialog-title">${title}</h2></div>${btn('','close-dialog','close','ghost iconbtn','aria-label="Close dialog" autofocus')}</header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</div>`;if(!d.open)d.showModal();}
function openRecord(id,tab='summary'){state.dialogType='record';state.selected=id;state.dialogTab=tab;const r=records.find(r=>r.id===id)||records[0];let content=tab==='summary'?`<div class="dialog-callout">${badge('Rejected · simulation failed','warn')}<h3>Net result is unknown</h3><p>Costs are incomplete. This record is not a realized trading result.</p></div><dl class="summary-list"><div><dt>Record</dt><dd class="mono">${r.id}</dd></div><div><dt>Mode / network</dt><dd>PAPER / Base</dd></div><div><dt>Start asset</dt><dd class="mono">${r.asset}</dd></div><div><dt>Input · minor units</dt><dd class="mono">${r.input}</dd></div><div><dt>Quoted output · minor units</dt><dd class="mono">${r.output}</dd></div><div><dt>Gross delta · minor units</dt><dd class="mono">+60000</dd></div><div><dt>Net after explicit costs</dt><dd>Unknown — costs incomplete</dd></div><div><dt>Observed at</dt><dd class="mono">2026-09-12 12:00:00 UTC</dd></div></dl><p class="form-help space">Raw minor units preserve precision. Start-asset decimals are not supplied by this API. The fixture is not an execution plan.</p>`:tab==='route'?`<h3>Route and eligibility</h3><div class="steps-route">${[['$','USDC'],['Ξ','WETH'],['$','USDC']].map(([i,t],n)=>`${n?icon('arrow'):''}<div class="route-step"><span class="token">${i}</span>${t}</div>`).join('')}</div><div class="route-venues"><div class="venue"><strong>Leg 01 · Uniswap v3</strong>fixture:pool-a</div><div class="venue"><strong>Leg 02 · Uniswap v3</strong>fixture:pool-b</div></div><dl class="summary-list space"><div><dt>Fresh / coherent at evaluation</dt><dd>Pass — fixture only</dd></div><div><dt>Atomic route support</dt><dd>Not satisfied</dd></div><div><dt>Final balance guard</dt><dd>Not satisfied</dd></div><div><dt>Costs complete</dt><dd>Not satisfied</dd></div><div><dt>Principal / fee reservation</dt><dd>Not satisfied</dd></div><div><dt>Simulation matches exact plan</dt><dd>Not satisfied</dd></div></dl><div class="inline-message space"><p><strong>NETWORK_COST_UNKNOWN</strong><br>Simulation: FAILED. A partial network-fee value does not make all costs complete.</p></div><dl class="summary-list"><div><dt>Network fee · start-asset minor units</dt><dd class="mono">30000</dd></div><div><dt>Native amount · minor units</dt><dd class="mono">10000000000000</dd></div><div><dt>Valuation</dt><dd class="mono">fixture-only-conversion-3000-usdc-per-eth</dd></div></dl>`:`<h3>Original provenance</h3><p class="subtle space">Refreshing the source status must never refresh the historical captured price.</p><dl class="summary-list space"><div><dt>Source kind</dt><dd>${badge('Synthetic dataset')}</dd></div><div><dt>Observed</dt><dd class="mono">${r.observed}</dd></div><div><dt>State reference</dt><dd class="mono">fixture:block:1</dd></div><div><dt>Snapshot</dt><dd class="mono">fixture-snapshot-001</dd></div><div><dt>Provider</dt><dd class="mono">synthetic-unit-fixture</dd></div><div><dt>Age at evaluation</dt><dd>0 ms · fixture-only</dd></div><div><dt>Finality</dt><dd>NOT_APPLICABLE</dd></div><div><dt>Execution plan</dt><dd>Not supplied</dd></div><div><dt>Inclusion scenario</dt><dd>Not supplied</dd></div></dl><div class="raw-block">${esc(JSON.stringify(r,null,2))}</div>`;
openDialog('Captured market record',`${drawerTabs([['summary','Summary'],['route','Route & costs'],['provenance','Provenance']],tab)}${content}`,{drawer:true,eyebrow:'Captured data only / record-1',footer:`<p>Synthetic evidence.<br>No execution or trading controls.</p>${btn('Export record','export-record','download','small')}`});}
function drawerTabs(items,active){return `<div class="tabs" role="tablist" aria-label="Inspection sections">${items.map(([id,t])=>`<button class="tab ${active===id?'active':''}" role="tab" aria-selected="${active===id}" tabindex="${active===id?'0':'-1'}" data-action="drawer-tab" data-tab="${id}">${t}</button>`).join('')}</div>`;}
function openDecision(id,tab='decision'){state.dialogType='decision';state.selected=id;const d=decisions.find(d=>d.id===id)||decisions[0];const body=tab==='decision'?`<div class="dialog-callout">${badge(d.state+' · '+d.reason,d.state==='REJECTED'?'warn':'')}<h3>${d.gross===null?'No established net outcome':'Gross quote, not profit'}</h3><p>External costs and full transaction simulation are not established by this observation.</p></div><dl class="summary-list"><div><dt>Observation</dt><dd class="mono">${d.id}</dd></div><div><dt>Session / mode</dt><dd>session-paper / PAPER</dd></div><div><dt>Network</dt><dd>base-mainnet</dd></div><div><dt>Observed</dt><dd class="mono">2026-09-12T12:00:00.000Z</dd></div><div><dt>Stored</dt><dd class="mono">2026-09-12T12:00:00.001Z</dd></div><div><dt>Capture / evaluation elapsed</dt><dd>15 ms · processing duration, not chain age</dd></div><div><dt>Frozen configuration</dt><dd class="mono">sha256:paper-fixture-config</dd></div><div><dt>Gross delta · minor units</dt><dd class="mono">${d.gross===null?'Unknown':'+'+d.gross}</dd></div><div><dt>Net result</dt><dd>Unknown</dd></div></dl><div class="inline-message neutral space"><p>All content in this prototype is synthetic, including any reproduced inner “recorded live input” origin label.</p></div>`:`<div class="dialog-callout">${badge('Continuity only')}<h3>No known source invalidation</h3><p>Fixture status only. This is not a freshness, simulation, profitability or authorization check.</p></div><dl class="summary-list"><div><dt>Database check received</dt><dd class="mono">2026-09-17T08:00:00.000Z</dd></div><div><dt>Bound capture references</dt><dd>2 of 2</dd></div><div><dt>Continuity policy</dt><dd class="mono">base-capture-continuity-v1</dd></div><div><dt>Historical decision</dt><dd>Unchanged</dd></div></dl><p class="form-help space">Source continuity, data freshness, tick coverage, simulation, costs and profitability require separate evidence.</p>`;
openDialog('Decision evidence detail',drawerTabs([['decision','Decision'],['continuity','Source continuity']],tab)+body,{drawer:true,eyebrow:'Persisted evidence / synthetic fixture',footer:`<p>The historical observation<br>is never overwritten.</p>${d.gross!==null?btn('Assess costs','go-cost','arrow','primary'):btn('Close','close-dialog','','')}`});}
function permitted(s){if(s.state==='RECOVERING')return[];if(s.state==='STOPPED')return['START'];if(s.state==='RUNNING')return['PAUSE','STOP'];if(s.state==='PAUSED')return['RESUME','STOP'];if(s.state==='DRAINING')return['STOP'];return[];}
function stoppable(){return availableSessions().filter(s=>permitted(s).includes('STOP')&&state.receipts[s.id]?.status!=='PENDING');}
function openSession(id){state.dialogType='session';state.selected=id;const s=state.sessions.find(x=>x.id===id);if(!s)return;const rec=state.receipts[id];const body=`<div class="dialog-callout"><div class="flex spread">${stateBadge(s.state)}${badge(s.mode)}</div><h3>${s.unresolved?`${s.unresolved} attempts remain unresolved`:s.state==='RUNNING'?'Observed as running':s.state==='RECOVERING'?'Readiness is not confirmed':s.state==='PAUSED'?'New evaluation is paused':'Session is stopped'}</h3><p>${s.unresolved?'The admission fence has applied. A stop cannot recall an emitted transaction; reconciliation must continue.':'Observed state is separate from requested state. These are synthetic interface fixtures.'}</p></div><dl class="summary-list"><div><dt>Session</dt><dd class="mono">${s.id}</dd></div><div><dt>Network / immutable mode</dt><dd>${s.network==='base'?'Base':'Solana'} / ${s.mode}</dd></div><div><dt>Health field</dt><dd>${s.health} · fixture value</dd></div><div><dt>Desired / applied revision</dt><dd class="mono">${s.desired} / ${s.applied}</dd></div><div><dt>Unresolved attempts</dt><dd class="mono">${s.unresolved}</dd></div><div><dt>Last worker heartbeat</dt><dd class="mono">${s.heartbeat||'Unknown — no heartbeat reported'}</dd></div><div><dt>Configuration</dt><dd class="mono">${s.config}</dd></div></dl>${s.desired!==s.applied?`<div class="inline-message neutral space"><p>Desired and applied revisions differ. This can reflect unapplied, rejected or superseded history; a revision gap alone does not establish a pending worker acknowledgement.</p></div>`:''}<h3 class="space">Session controls</h3><p class="subtle" style="margin-top:8px">These preview controls target only ${s.id}. No server command is sent.</p><div class="command-buttons">${['START','PAUSE','RESUME','STOP'].map(a=>btn(a[0]+a.slice(1).toLowerCase(),'session-command',a==='START'||a==='RESUME'?'play':a==='PAUSE'?'pause':'stop',a==='STOP'?'danger':'',`data-id="${s.id}" data-command="${a}" ${!permitted(s).includes(a)||rec?.status==='PENDING'?'disabled':''}`)).join('')}</div>${s.state==='RECOVERING'?btn('Simulate readiness check','ready','check','space',`data-id="${s.id}"`):''}${rec?`<div class="command-receipt">${badge(rec.status==='PENDING'?'Request pending':'Applied · simulated',rec.status==='PENDING'?'warn':'')}<p><strong>${rec.action}</strong> for ${s.id}. ${rec.status==='PENDING'?'The observed worker state has not changed.':'The fixture acknowledgement was applied locally.'}</p><p class="mono break">${rec.key}</p>${rec.status==='PENDING'?btn('Simulate worker acknowledgement','ack','check','',`data-id="${s.id}"`):''}</div>`:''}${s.state==='DRAINING'&&s.unresolved?`<div class="inline-message space"><p>The session cannot become STOPPED while outcomes remain unresolved.</p>${btn('Simulate reconciliation','reconcile','check','small space',`data-id="${s.id}"`)}</div>`:''}`;
openDialog(s.name,body,{drawer:true,eyebrow:'Research session / immutable',footer:`<p>Command receipts are explicit.<br>No automatic success state.</p>${btn('Close','close-dialog','','small')}`});}
function openSearch(){state.dialogType='search';openDialog('Search workspace',`<div class="search" style="position:relative">${icon('search')}<label class="sr-only" for="global-search">Search pages and evidence</label><input id="global-search" placeholder="Pages, sessions, or record-1…" autocomplete="off"></div><div class="search-results" id="search-results">${searchResults('')}</div>`,{eyebrow:'Find a page, session or record / ⌘ K'});setTimeout(()=>$('#global-search')?.focus(),50);}
function searchResults(q){const targets=[...NAV.map(([id,t])=>({title:t,type:'Workspace',action:'search-nav',id})),...state.sessions.map(s=>({title:s.name+' · '+s.id,type:'Session',action:'session',id:s.id})),{title:'record-1 · USDC → WETH → USDC',type:'Evidence',action:'record',id:'record-1'}];const rr=targets.filter(t=>t.title.toLowerCase().includes(q.toLowerCase()));return rr.length?rr.map(t=>`<button class="search-result" data-action="${t.action}" data-id="${t.id}">${icon(t.type==='Session'?'runs':t.type==='Evidence'?'file':'arrow')}<span class="grow">${esc(t.title)}</span><span class="subtle">${t.type}</span></button>`).join(''):'<p class="subtle" style="padding:20px">No matching page, session or fixture record.</p>';}
function openPreview(){state.dialogType='preview';openDialog('Preview interface states',`<p class="subtle" style="margin-bottom:20px">These controls affect this offline prototype only. They do not test a backend.</p><div class="preview-settings">${[['snapshot','Fixture snapshot','The reviewed synthetic examples, with their original timestamps.'],['stale','Stale / last known','Retain evidence and expose staleness without manufacturing new results.'],['error','Connection error','Keep the last known snapshot visible with a distinct error notice.'],['empty','Empty data','No loaded sessions or captured records. No fabricated statistics.'],['loading','Loading','An explicit loading state; no fallback market data.']].map(([id,t,p])=>`<button class="preview-option ${state.scenario===id?'active':''}" data-action="scenario" data-id="${id}"><span class="choice-circle"></span><span><strong>${t}</strong><p>${p}</p></span></button>`).join('')}</div><p class="form-help space">Scenario states are demonstrated on Overview and the primary sessions / captured-evidence views. Secondary research tabs retain their labelled layout fixtures.</p>`);}
function openAccount(){openDialog('Workspace preferences',`<p class="subtle">Private workspace · offline design preview</p><div class="stack space">${btn('Switch colour theme','theme','sun')}${btn('Change password','password','lock')}${btn('View sign-in design','show-signin','logout')}</div><hr class="rule"><p class="form-help">No account is signed in here. No credentials are stored, submitted, or changed by this prototype.</p>`,{eyebrow:'Account & preferences'});}
function openMobileNav(){openDialog('Workspace',`<nav class="search-results" aria-label="All workspace pages">${NAV.map(([id,title])=>`<button class="search-result" data-action="search-nav" data-id="${id}">${icon(id)}<span>${title}</span>${state.page===id?'<span class="subtle">Selected</span>':''}</button>`).join('')}${btn('Real trading · unavailable','search-nav','lock','ghost','data-id="real"')}${btn('Account & preferences','account','strategies','ghost')}${btn('Preview interface states','preview','code','ghost')}</nav>`);}
function showConfig(id){let c=configFor(id);openDialog('Immutable configuration',`<div class="flex">${badge(c.mode)}${badge('Immutable')}</div><dl class="summary-list space"><div><dt>Configuration</dt><dd class="mono">${c.config}</dd></div><div><dt>Network</dt><dd>${c.network}</dd></div><div><dt>Strategy</dt><dd>usdc-cycle</dd></div><div><dt>Registry source</dt><dd>Synthetic preview catalog</dd></div></dl><div class="inline-message neutral space"><p>Virtual principal, separate native reserves, token eligibility and delay scenarios belong to the source configuration. They are not inferred from this summary.</p></div><p class="form-help">A change requires a new validated configuration version. Never mutate the digest, network or mode of an existing session.</p>`,{drawer:true,eyebrow:'Configuration register',footer:`<p>Synthetic configuration,<br>not execution authorization.</p>${btn('Use in experiment','use-config','arrow','primary',`data-id="${id}"`)}`});}
function download(name,data,type='application/json'){const b=new Blob([type==='application/json'?JSON.stringify(data,null,2):data],{type});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);announce('Downloaded synthetic preview data. No source was refreshed.');}
function csvCell(value){const s=String(value??'');return '"'+(/^[=+\-@\t\r]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"';}
function updateCostResult(){const net=exactCost();const el=$('#cost-result');if(el)el.textContent=net===null?'Unknown':(BigInt(net)>0?'+':'')+net;const comp=$('#cost-completeness');if(comp)comp.textContent=net===null?'Incomplete':'All six entered';const save=$('#save-cost');if(save)save.disabled=net===null||!state.costReview;}
function command(id,action){const s=state.sessions.find(x=>x.id===id);if(!s||!permitted(s).includes(action)||state.receipts[id]?.status==='PENDING')return;const key=`preview-${Date.now()}-${id}-${action}`;state.receipts[id]={action,status:'PENDING',key};render();openSession(id);announce(`${action} requested in the local fixture. Observed state remains ${s.state}.`);}
function ack(id){const s=state.sessions.find(x=>x.id===id),r=state.receipts[id];if(!s||!r||r.status!=='PENDING')return;if(r.action==='START'||r.action==='RESUME')s.state='RUNNING';if(r.action==='PAUSE')s.state='PAUSED';if(r.action==='STOP')s.state=s.unresolved?'DRAINING':'STOPPED';s.desired=(BigInt(s.desired)+1n).toString();s.applied=s.desired;r.status='APPLIED';render();openSession(id);announce(`Simulated acknowledgement applied. Fixture state is ${s.state}.`);}
function confirmStopAll(){const target=stoppable();openDialog(`Stop ${target.length} loaded sessions?`,`<p style="font-size:13px">This scope includes loaded sessions outside the current chain filter. These are <strong>local fixture requests only</strong>.</p><ul class="command-list space">${target.map(s=>`<li><span>${esc(s.name)}<br><span class="mono muted">${s.id}</span></span>${stateBadge(s.state)}</li>`).join('')}</ul><div class="inline-message space"><p>A stop request is not a worker acknowledgement. Previously emitted attempts may remain unresolved. Separately launched capture processes are not stopped by these controls.</p></div>`,{eyebrow:'Explicit control scope',footer:`${btn('Cancel','close-dialog','','')}${btn('Request fixture stops','confirm-stop-all','stop','danger')}`});}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const a=target.dataset.action,id=target.dataset.id;
if(a==='evidence-layout'){state.recordLayout=target.dataset.layout;render();document.querySelector(`[data-layout="${state.recordLayout}"]`)?.focus({preventScroll:true});announce(`Evidence layout changed to ${state.recordLayout}. Filters are preserved.`);}
else if(a==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('arb-mobbin-v3-theme',document.documentElement.dataset.theme);}catch{}render();document.querySelector('[data-action="theme"]')?.focus({preventScroll:true});announce('Colour theme changed.');}
else if(a==='close-dialog')$('#dialog').close();
else if(a==='preview')openPreview();
else if(a==='scenario'){state.scenario=id;state.lastPreviewRead=null;$('#dialog').close();render(true);announce(`Preview state: ${id}.`);}
else if(a==='restore'){state.scenario='snapshot';render();}
else if(a==='search')openSearch();
else if(a==='account')openAccount();
else if(a==='mobile-nav')openMobileNav();
else if(a==='search-nav'){if($('#dialog').open)$('#dialog').close();navigate(id);}
else if(a==='show-signin'){$('#dialog').close();navigate('signin');}
else if(a==='signin-help'){const help=$('#signin-help');help.hidden=!help.hidden;target.setAttribute('aria-expanded',String(!help.hidden));}
else if(a==='password')openDialog('Change password',`<p class="subtle">Production uses the existing account API. This design preview deliberately does not accept credentials.</p><div class="field space"><label for="current-pass">Current password</label><input id="current-pass" type="password" disabled></div><div class="field space"><label for="new-pass">New password</label><input id="new-pass" type="password" disabled></div><div class="field space"><label for="confirm-pass">Confirm new password</label><input id="confirm-pass" type="password" disabled></div><p class="form-help space">No password has been changed. Existing production authentication and recovery semantics must be preserved.</p>`,{footer:btn('Change password','noop','lock','primary','disabled')});
else if(a==='refresh'){state.lastPreviewRead=Date.now();render();announce('Synthetic fixture re-read. Captured source times unchanged.');}
else if(a==='reset-filter'){state.chain='all';state.query='';state.evidence='all';if(state.scenario==='empty')state.scenario='snapshot';render();}
else if(a==='tab'){state.tab=target.dataset.tab;history.replaceState(null,'',`#/${state.page}?tab=${state.tab}`);render();$('#tab-'+state.tab)?.focus({preventScroll:true});}
else if(a==='record')openRecord(id);
else if(a==='decision')openDecision(id);
else if(a==='drawer-tab'){const tab=target.dataset.tab;if(state.dialogType==='record')openRecord(state.selected,tab);else if(state.dialogType==='decision')openDecision(state.selected,tab);$('#dialog .tab.active')?.focus();}
else if(a==='go-cost'){$('#dialog').close();navigate('opportunities','costs');}
else if(a==='session')openSession(id);
else if(a==='session-command'){const cmd=target.dataset.command;const s=state.sessions.find(x=>x.id===id);openDialog(`${cmd[0]+cmd.slice(1).toLowerCase()} ${esc(s.name)}?`,`<p style="font-size:13px">Target: <span class="mono">${s.id}</span></p><div class="inline-message neutral space"><p>Only this immutable ${s.mode} session is targeted. A local request receipt will be created; the observed state stays unchanged until you explicitly simulate a worker acknowledgement.</p></div><p class="form-help">No backend or trading operation is performed.</p>`,{eyebrow:'Preview command confirmation',footer:`${btn('Cancel','session','','',`data-id="${id}"`)}${btn('Request '+cmd.toLowerCase(),'confirm-command',cmd==='STOP'?'stop':'arrow',cmd==='STOP'?'danger':'primary',`data-id="${id}" data-command="${cmd}"`)}`});}
else if(a==='confirm-command')command(id,target.dataset.command);
else if(a==='ack')ack(id);
else if(a==='ready'){const s=state.sessions.find(x=>x.id===id);if(s&&s.state==='RECOVERING'){s.state='STOPPED';render();openSession(id);announce('Fixture readiness simulated. Session is stopped, not running.');}}
else if(a==='reconcile'){const s=state.sessions.find(x=>x.id===id);if(s&&s.state==='DRAINING'){s.unresolved=0;s.state='STOPPED';render();openSession(id);announce('Fixture reconciliation simulated. Zero unresolved attempts; state is stopped.');}}
else if(a==='stop-all')confirmStopAll();
else if(a==='confirm-stop-all'){stoppable().forEach(s=>{state.receipts[s.id]={action:'STOP',status:'PENDING',key:`preview-bulk-${Date.now()}-${s.id}`};});$('#dialog').close();render();announce('Local stop requests are pending. Observed session states are unchanged.');}
else if(a==='create-session'){if(!state.form.review||!state.form.reference.trim())return;const c=configFor(state.form.config);const sid='preview-session-'+(state.sessions.length+1);state.sessions.push({id:sid,name:state.form.reference.trim(),network:c.network,mode:c.mode,state:'RECOVERING',health:'UNKNOWN',desired:'0',applied:'0',unresolved:0,heartbeat:null,config:c.config});state.chain='all';state.form.review=false;render();openSession(sid);announce('Preview session created locally. Recovery is required; no worker has started.');}
else if(a==='config')showConfig(id);
else if(a==='use-config'){state.form.config=id;state.form.review=false;$('#dialog').close();navigate('experiments');}
else if(a==='save-cost'){const n=exactCost();if(n!==null&&state.costReview){state.assessment={source:'SYNTHETIC_UI_PROTOTYPE',net:n,units:'start-asset minor units',costs:structuredClone(state.costs),originalObservation:'observation-fixture'};render();announce('Local hypothetical scenario retained. No paper booking or server write.');}}
else if(a==='freeze'){state.frozen=structuredClone({kind:'SYNTHETIC_DESIGN_EXPORT',scope:'Selected fixture samples only; not a complete database export',session:'session-paper',fixtureSnapshot:FIXTURE_AT,frozenAt:new Date().toISOString(),records,decisions,costAssessments:state.assessment?[state.assessment]:[],rawArtifactsIncluded:false,integrityVerified:false});render();announce('Synthetic sample frozen locally. Future page changes do not update this export.');}
else if(a==='export-json'&&state.frozen)download('arbitrage-frozen-design-fixture.json',state.frozen);
else if(a==='export-csv'&&state.frozen){const fields=['kind','record_id','network','input_minor_units','quoted_output_minor_units','net_minor_units','reason','origin','fixture_snapshot'];const lines=[fields.map(csvCell).join(','),...state.frozen.records.map(r=>['SYNTHETIC_DESIGN_EXPORT',r.id,r.network,r.input,r.output,'UNKNOWN',r.reason,'SYNTHETIC_UI_FIXTURE',state.frozen.fixtureSnapshot].map(csvCell).join(','))];download('arbitrage-captured-design-fixture.csv',lines.join('\r\n'),'text/csv;charset=utf-8');}
else if(a==='export-record')download('arbitrage-record-design-fixture.json',{kind:'SYNTHETIC_UI_PROTOTYPE',...records[0]});
else if(a==='export-ledger')download('arbitrage-ledger-design-fixture.json',{kind:'SYNTHETIC_UI_PROTOTYPE',asset:'fixture:base:native-fee-asset',units:'minor units',free:'80',reserved:'20',total:'100',performanceClaim:false});
else if(a==='run-fields')openDialog('Hypothetical run creation',`<p class="subtle">Presentation contract for the existing production form.</p><dl class="summary-list space"><div><dt>Paper session</dt><dd>Explicit immutable session scope</dd></div><div><dt>Principal asset</dt><dd>Validated contract or mint identity</dd></div><div><dt>Initial principal</dt><dd>Exact integer minor units</dd></div><div><dt>Native fee reserve</dt><dd>Separate asset; exact minor units</dd></div><div><dt>Configuration review</dt><dd>Required acknowledgement</dd></div><div><dt>After creation</dt><dd>New immutable ledger; old runs unchanged</dd></div></dl><p class="form-help space">No wallet key, token approval, settlement or transfer controls belong here.</p>`,{eyebrow:'Implementation handoff / not connected'});
});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='global-search')$('#search-results').innerHTML=searchResults(t.value);if(t.id==='record-search'){state.query=t.value;$('#records-area').innerHTML=recordTable();}if(t.id==='experiment-reference'){state.form.reference=t.value;$('#create-session').disabled=!state.form.review||!t.value.trim();}if(t.dataset.costValue!==undefined){state.costs[Number(t.dataset.costValue)].value=t.value;updateCostResult();}});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='chain-filter'){state.chain=t.value;render();announce('View filter changed. Session mode and control scope are unchanged.');}if(t.id==='evidence-filter'){state.evidence=t.value;$('#records-area').innerHTML=recordTable();}if(t.id==='experiment-config'){state.form.config=t.value;state.form.review=false;render();}if(t.id==='experiment-review'){state.form.review=t.checked;$('#create-session').disabled=!t.checked||!state.form.reference.trim();}if(t.dataset.costKind!==undefined){const i=Number(t.dataset.costKind);state.costs[i].kind=t.value;const v=$('#cost-value-'+i);v.disabled=t.value!=='known';updateCostResult();}if(t.id==='cost-review'){state.costReview=t.checked;updateCostResult();}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!$('#dialog').open){event.preventDefault();openSearch();}if(['ArrowRight','ArrowLeft','Home','End'].includes(event.key)&&document.activeElement?.getAttribute('role')==='tab'){event.preventDefault();const ts=[...document.activeElement.parentElement.querySelectorAll('[role=tab]')];let i=ts.indexOf(document.activeElement);i=event.key==='Home'?0:event.key==='End'?ts.length-1:(i+(event.key==='ArrowRight'?1:-1)+ts.length)%ts.length;ts[i].click();}});
$('#dialog').addEventListener('close',()=>{state.dialogType='';if(focusReturn?.isConnected)focusReturn.focus({preventScroll:true});else $('h1')?.focus({preventScroll:true});});
window.addEventListener('hashchange',route);
route();

